mapper.update:
UPDATE product
SET is_deleted = 1, updated_at = now(), updated_by = #{updatedBy}
WHERE product_id = #{productId} AND is_deleted = 0

UPDATE product
SET is_deleted = 0, updated_at = now(), updated_by = #{updatedBy}
WHERE product_id = #{productId} AND is_deleted = 1

UPDATE product
SET is_active = #{isActive}, updated_at = now(), updated_by = #{updatedBy}
WHERE product_id = #{productId} AND is_deleted = 0

mapper.select:
SELECT COUNT(1)
FROM product


        (name ILIKE '%' || #{q} || '%' OR short_description ILIKE '%' || #{q} || '%')

    AND brand_id = #{brandId}
    AND category_id = #{categoryId}
    AND price >= #{minPrice}
    AND price <= #{maxPrice}

        AND is_active =

            1
            0


    AND stock_quantity > 0

        AND attributes::text ILIKE CONCAT('%', #{attributesContains}, '%')

    AND is_deleted = 0
